using System.Buffers.Binary;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
var root=Directory.GetCurrentDirectory();using var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(root,"docs/coredrp-v1-test-vectors.json")));var data=doc.RootElement;var tags=data.GetProperty("domain_tags_ascii");byte[] Pay=Encoding.ASCII.GetBytes(tags.GetProperty("payload").GetString()!),Evt=Encoding.ASCII.GetBytes(tags.GetProperty("event").GetString()!),Gen=Encoding.ASCII.GetBytes(tags.GetProperty("genesis").GetString()!);
static byte[] U16(int n){var b=new byte[2];BinaryPrimitives.WriteUInt16BigEndian(b,(ushort)n);return b;}static byte[] U32(int n){var b=new byte[4];BinaryPrimitives.WriteUInt32BigEndian(b,(uint)n);return b;}static byte[] U64(ulong n){var b=new byte[8];BinaryPrimitives.WriteUInt64BigEndian(b,n);return b;}static byte[] I64(long n){var b=new byte[8];BinaryPrimitives.WriteInt64BigEndian(b,n);return b;}static byte[] Cat(params byte[][] xs){var r=new byte[xs.Sum(x=>x.Length)];int o=0;foreach(var x in xs){Buffer.BlockCopy(x,0,r,o,x.Length);o+=x.Length;}return r;}static byte[] H(byte[] b)=>SHA256.HashData(b);static string Hex(byte[] b)=>Convert.ToHexString(b).ToLowerInvariant();
foreach(var c in data.GetProperty("chains").EnumerateArray()){var sender=new Guid(c.GetProperty("sender_id").GetString()!).ToByteArray(bigEndian:true);if(Hex(sender)!=c.GetProperty("sender_id_bytes_hex").GetString())throw new Exception("RFC9562 UUID order");var epoch=new Guid(c.GetProperty("log_epoch").GetString()!).ToByteArray(bigEndian:true);int lane=c.GetProperty("lane_id").GetInt32();var g=Cat(Gen,sender,epoch,new[]{(byte)lane});if(Hex(g)!=c.GetProperty("genesis_preimage_hex").GetString())throw new Exception("genesis");var chain=H(g);foreach(var e in c.GetProperty("events").EnumerateArray()){ulong seq=e.GetProperty("sequence").GetUInt64();int et=Convert.ToInt32(e.GetProperty("event_type").GetString(),16);var rid=new Guid(e.GetProperty("relay_event_id").GetString()!).ToByteArray(bigEndian:true);var scope=Convert.FromHexString(e.GetProperty("scope_hex").GetString()!);long tm=e.GetProperty("event_time_unix_ms").GetInt64();var payload=Convert.FromHexString(e.GetProperty("payload_hex").GetString()!);var ph=H(Cat(Pay,U32(payload.Length),payload));var pre=Cat(Evt,chain,sender,epoch,new[]{(byte)lane},U64(seq),U16(et),rid,U16(scope.Length),scope,I64(tm),ph);if(Hex(pre)!=e.GetProperty("event_preimage_hex").GetString())throw new Exception("preimage");chain=H(pre);if(Hex(chain)!=e.GetProperty("chain_hash_sha256").GetString())throw new Exception("hash");}}Console.WriteLine("CoreDRP C# vectors: OK");
